//! The Codex app-server protocol (JSON-RPC over stdio, one JSON object per line, no
//! `"jsonrpc"` field), as generated by `codex app-server generate-json-schema` for codex 0.147.0,
//! and how its v2 notifications map onto rozu's [`StreamEvent`]s.
//!
//! | notification | rozu |
//! |---|---|
//! | `item/agentMessage/delta` | text delta |
//! | `item/started` (`commandExecution`, `fileChange`, `mcpToolCall`, `webSearch`, `dynamicToolCall`) | tool call start + args + end |
//! | `item/completed` (same types) | [`StreamEvent::ToolResult`]; `agentMessage` text if no deltas came |
//! | `thread/tokenUsage/updated` | kept; the turn's [`Usage`] is the change in the thread `total` |
//! | `turn/completed` | usage, then done (`completed`), cancelled (`interrupted`) or a typed error (`failed`) |
//! | `error` | remembered for the failed turn's message (unless `willRetry`) |
//! | anything else (reasoning, plan, diff, account, MCP startup, …) | logged at debug |
//!
//! Notifications for another thread are skipped.

use std::collections::{HashMap, HashSet};

use rozu_core::{ProviderError, StopReason, StreamEvent, Usage};
use serde_json::{Value, json};
use tracing::{debug, info, warn};

/// The hint shown when Codex isn't logged in.
pub const LOGIN_HINT: &str = "run `rozu auth login codex` (it runs the official `codex login`; \
     rozu never handles ChatGPT credentials)";

/// The JSON-RPC error code rozu answers unsupported server requests with.
pub const METHOD_NOT_FOUND: i64 = -32601;

/// Tool name rozu shows for a Codex shell command.
pub const SHELL_TOOL: &str = "codex:shell";
/// Tool name rozu shows for a Codex file change (its `apply_patch`).
pub const PATCH_TOOL: &str = "codex:apply_patch";

/// One message from the app-server.
#[derive(Debug, Clone, PartialEq)]
pub enum Incoming {
    /// The answer to one of rozu's requests.
    Response {
        id: Value,
        result: Result<Value, String>,
    },
    /// A server → client request rozu must answer.
    Request {
        id: Value,
        method: String,
        params: Value,
    },
    Notification {
        method: String,
        params: Value,
    },
}

impl Incoming {
    /// `None` for something that isn't a JSON-RPC message.
    pub fn parse(message: Value) -> Option<Self> {
        let Value::Object(mut map) = message else {
            return None;
        };
        let method = map.get("method").and_then(Value::as_str).map(str::to_owned);
        let params = map.remove("params").unwrap_or(Value::Null);
        match (method, map.remove("id")) {
            (Some(method), Some(id)) => Some(Self::Request { id, method, params }),
            (Some(method), None) => Some(Self::Notification { method, params }),
            (None, Some(id)) => {
                let result = match (map.remove("result"), map.remove("error")) {
                    (_, Some(error)) => Err(error["message"]
                        .as_str()
                        .map_or_else(|| error.to_string(), str::to_owned)),
                    (Some(result), None) => Ok(result),
                    (None, None) => return None,
                };
                Some(Self::Response { id, result })
            }
            (None, None) => None,
        }
    }
}

pub fn request(id: u64, method: &str, params: Value) -> Value {
    json!({ "id": id, "method": method, "params": params })
}

pub fn notification(method: &str) -> Value {
    json!({ "method": method })
}

pub fn response(id: &Value, result: Value) -> Value {
    json!({ "id": id, "result": result })
}

pub fn error_response(id: &Value, code: i64, message: &str) -> Value {
    json!({ "id": id, "error": { "code": code, "message": message } })
}

/// `initialize` params: rozu's client info; no experimental API, no attestation.
pub fn initialize_params() -> Value {
    json!({
        "clientInfo": {
            "name": "rozu",
            "title": "rozu",
            "version": env!("CARGO_PKG_VERSION"),
        },
        "capabilities": { "experimentalApi": false },
    })
}

/// The `input` of `turn/start` for a text message.
pub fn text_input(text: &str) -> Value {
    json!([{ "type": "text", "text": text, "text_elements": [] }])
}

/// What `account/read` says about the login. Only the account *type* is kept; the e-mail and
/// plan in the response are never read.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum AccountStatus {
    /// Logged in; the auth mode (`chatgpt`, `apiKey`, `amazonBedrock`, …).
    LoggedIn(String),
    /// No account, and the provider needs an OpenAI login.
    NotLoggedIn,
    /// No account, but none is needed (e.g. a custom model provider).
    NotRequired,
}

pub fn account_status(result: &Value) -> AccountStatus {
    match result["account"]["type"].as_str() {
        Some(mode) => AccountStatus::LoggedIn(mode.chars().take(32).collect()),
        None if result["requiresOpenaiAuth"].as_bool() == Some(false) => AccountStatus::NotRequired,
        None => AccountStatus::NotLoggedIn,
    }
}

/// Codex's `TokenUsageBreakdown` → rozu's [`Usage`].
///
/// `inputTokens` already includes the cached part (OpenAI's convention, and rozu's), so it maps
/// to `input_tokens` as is; `cachedInputTokens` → `cache_read_tokens`; `cacheWriteInputTokens`
/// (schema default 0, OpenAI doesn't bill cache writes) → `cache_write_tokens`;
/// `outputTokens` (which includes `reasoningOutputTokens`) → `output_tokens`.
pub fn usage_from_codex(breakdown: &Value) -> Usage {
    let n = |key: &str| breakdown[key].as_u64().unwrap_or(0);
    Usage {
        input_tokens: n("inputTokens"),
        output_tokens: n("outputTokens"),
        cache_read_tokens: n("cachedInputTokens"),
        cache_write_tokens: n("cacheWriteInputTokens"),
    }
}

/// `later - earlier`, field by field (a thread's running totals → one turn's usage).
pub fn usage_delta(later: Usage, earlier: Usage) -> Usage {
    Usage {
        input_tokens: later.input_tokens.saturating_sub(earlier.input_tokens),
        output_tokens: later.output_tokens.saturating_sub(earlier.output_tokens),
        cache_read_tokens: later
            .cache_read_tokens
            .saturating_sub(earlier.cache_read_tokens),
        cache_write_tokens: later
            .cache_write_tokens
            .saturating_sub(earlier.cache_write_tokens),
    }
}

/// A failed turn's `TurnError` (or an `error` notification) as a typed error.
pub fn classify_turn_error(error: &Value) -> ProviderError {
    let message = error["message"].as_str().unwrap_or("turn failed").trim();
    let info = &error["codexErrorInfo"];
    let code = info
        .as_str()
        .map(str::to_owned)
        .or_else(|| info.as_object().and_then(|o| o.keys().next().cloned()));
    let lower = message.to_lowercase();
    match code.as_deref() {
        Some("unauthorized") => ProviderError::NotLoggedIn {
            cli: "codex".into(),
            hint: LOGIN_HINT.into(),
        },
        Some("usageLimitExceeded") => ProviderError::UsageLimit {
            message: message.to_owned(),
        },
        _ if looks_logged_out(&lower) => ProviderError::NotLoggedIn {
            cli: "codex".into(),
            hint: LOGIN_HINT.into(),
        },
        _ if lower.contains("usage limit") || lower.contains("rate limit") => {
            ProviderError::UsageLimit {
                message: message.to_owned(),
            }
        }
        _ => ProviderError::Api {
            code: code.or_else(|| Some("codex".into())),
            message: message.to_owned(),
        },
    }
}

/// Whether CLI output (lowercased) says it isn't logged in.
pub fn looks_logged_out(lower: &str) -> bool {
    [
        "not logged in",
        "codex login",
        "please log in",
        "401 unauthorized",
    ]
    .iter()
    .any(|needle| lower.contains(needle))
}

/// What one notification meant for the turn.
#[derive(Debug, Default, PartialEq)]
pub struct Step {
    pub events: Vec<StreamEvent>,
    /// The turn is over (its `turn/completed` arrived).
    pub done: bool,
    /// The turn failed; ends the stream.
    pub error: Option<ProviderError>,
}

/// Maps the notifications of one thread, turn by turn. Keep one per thread: it holds the
/// thread's running token totals.
#[derive(Debug, Default)]
pub struct Mapper {
    thread_id: String,
    /// Agent-message items whose text arrived as deltas (the completed item repeats it).
    streamed: HashSet<String>,
    /// Tool-like items already announced to rozu.
    started: HashSet<String>,
    /// Items of the current turn by id (`fileChange` approvals refer to them for the diff).
    items: HashMap<String, Value>,
    /// The thread's token totals at the end of the previous turn, and the latest seen.
    baseline: Usage,
    latest: Option<Usage>,
    /// The last non-retried `error` notification, for a failed turn without its own error.
    last_error: Option<Value>,
}

impl Mapper {
    pub fn new(thread_id: impl Into<String>) -> Self {
        Self {
            thread_id: thread_id.into(),
            ..Self::default()
        }
    }

    pub fn thread_id(&self) -> &str {
        &self.thread_id
    }

    /// An item of the current turn (`item/started` or later), by id.
    pub fn item(&self, id: &str) -> Option<&Value> {
        self.items.get(id)
    }

    /// Forgets the per-turn state (the token totals stay).
    pub fn start_turn(&mut self) {
        self.streamed.clear();
        self.started.clear();
        self.items.clear();
        self.last_error = None;
    }

    pub fn map(&mut self, method: &str, params: &Value) -> Step {
        let mut step = Step::default();
        if params["threadId"]
            .as_str()
            .is_some_and(|id| id != self.thread_id)
        {
            debug!(target: "rozu::cli", method, "notification for another thread");
            return step;
        }
        match method {
            "item/agentMessage/delta" => {
                let delta = params["delta"].as_str().unwrap_or_default();
                if !delta.is_empty() {
                    if let Some(id) = params["itemId"].as_str() {
                        self.streamed.insert(id.to_owned());
                    }
                    step.events.push(StreamEvent::TextDelta(delta.to_owned()));
                }
            }
            "item/started" => self.item_started(&params["item"], &mut step.events),
            "item/completed" => self.item_completed(&params["item"], &mut step.events),
            "thread/tokenUsage/updated" => {
                let usage = &params["tokenUsage"];
                info!(target: "rozu::usage", provider = "codex", usage_raw = %usage,
                    reasoning_output_tokens = usage["total"]["reasoningOutputTokens"].as_u64().unwrap_or(0),
                    "token usage");
                if usage["total"].is_object() {
                    self.latest = Some(usage_from_codex(&usage["total"]));
                }
            }
            "error" => {
                let retry = params["willRetry"].as_bool().unwrap_or(false);
                warn!(target: "rozu::cli", will_retry = retry,
                    message = params["error"]["message"].as_str().unwrap_or(""), "codex error");
                if !retry {
                    self.last_error = Some(params["error"].clone());
                }
            }
            "turn/completed" => {
                let turn = &params["turn"];
                if let Some(total) = self.latest {
                    step.events
                        .push(StreamEvent::Usage(usage_delta(total, self.baseline)));
                    self.baseline = total;
                }
                match turn["status"].as_str() {
                    Some("completed") => {
                        step.events.push(StreamEvent::Done(StopReason::EndTurn));
                    }
                    Some("interrupted") => step.error = Some(ProviderError::Cancelled),
                    _ => {
                        let error = if turn["error"].is_object() {
                            turn["error"].clone()
                        } else {
                            self.last_error
                                .take()
                                .unwrap_or_else(|| json!({ "message": "the codex turn failed" }))
                        };
                        step.error = Some(classify_turn_error(&error));
                    }
                }
                step.done = true;
            }
            other => debug!(target: "rozu::cli", method = other, "ignored codex notification"),
        }
        step
    }

    fn item_started(&mut self, item: &Value, out: &mut Vec<StreamEvent>) {
        let Some(id) = item["id"].as_str() else {
            return;
        };
        self.items.insert(id.to_owned(), item.clone());
        if let Some((name, args)) = tool_call(item) {
            self.started.insert(id.to_owned());
            push_call(out, id, name, args);
        }
    }

    fn item_completed(&mut self, item: &Value, out: &mut Vec<StreamEvent>) {
        let Some(id) = item["id"].as_str() else {
            return;
        };
        self.items.insert(id.to_owned(), item.clone());
        if item["type"] == "agentMessage" {
            let text = item["text"].as_str().unwrap_or_default();
            if !self.streamed.contains(id) && !text.is_empty() {
                out.push(StreamEvent::TextDelta(text.to_owned()));
            }
            return;
        }
        let Some((name, args)) = tool_call(item) else {
            return;
        };
        if self.started.insert(id.to_owned()) {
            push_call(out, id, name, args);
        }
        let (output, is_error) = tool_result(item);
        out.push(StreamEvent::ToolResult {
            id: id.to_owned(),
            output,
            is_error,
        });
    }
}

fn push_call(out: &mut Vec<StreamEvent>, id: &str, name: String, args: Value) {
    out.push(StreamEvent::ToolCallStart {
        id: id.to_owned(),
        name,
    });
    out.push(StreamEvent::ToolCallArgsDelta {
        id: id.to_owned(),
        json: args.to_string(),
    });
    out.push(StreamEvent::ToolCallEnd { id: id.to_owned() });
}

/// The tool name and arguments rozu shows for a tool-like item.
fn tool_call(item: &Value) -> Option<(String, Value)> {
    Some(match item["type"].as_str()? {
        "commandExecution" => (
            SHELL_TOOL.to_owned(),
            json!({ "command": item["command"].as_str().unwrap_or_default() }),
        ),
        "fileChange" => {
            let files: Vec<Value> = item["changes"]
                .as_array()
                .into_iter()
                .flatten()
                .map(|c| json!({ "path": c["path"], "kind": c["kind"]["type"] }))
                .collect();
            (PATCH_TOOL.to_owned(), json!({ "files": files }))
        }
        "mcpToolCall" => {
            let server = item["server"].as_str().unwrap_or("?");
            let tool = item["tool"].as_str().unwrap_or("?");
            let name = if server == rozu_mcp::SERVER_NAME {
                tool.to_owned()
            } else {
                format!("{server}:{tool}")
            };
            (name, item["arguments"].clone())
        }
        "webSearch" => (
            "codex:web_search".to_owned(),
            json!({ "query": item["query"] }),
        ),
        "dynamicToolCall" => (
            format!("codex:{}", item["tool"].as_str().unwrap_or("tool")),
            item["arguments"].clone(),
        ),
        _ => return None,
    })
}

/// A completed tool-like item's output and whether it failed.
fn tool_result(item: &Value) -> (String, bool) {
    let status = item["status"].as_str().unwrap_or("completed");
    let failed = matches!(status, "failed" | "declined");
    match item["type"].as_str().unwrap_or_default() {
        "commandExecution" => {
            let mut output = item["aggregatedOutput"]
                .as_str()
                .unwrap_or_default()
                .to_owned();
            let exit = item["exitCode"].as_i64();
            if status == "declined" {
                output = "declined".to_owned();
            } else if let Some(code) = exit.filter(|code| *code != 0) {
                if !output.is_empty() && !output.ends_with('\n') {
                    output.push('\n');
                }
                output.push_str(&format!("[exit code {code}]"));
            }
            (output, failed || exit.is_some_and(|code| code != 0))
        }
        "fileChange" => {
            let paths: Vec<&str> = item["changes"]
                .as_array()
                .into_iter()
                .flatten()
                .filter_map(|c| c["path"].as_str())
                .collect();
            let verb = match status {
                "declined" => "declined",
                "failed" => "failed",
                _ => "applied",
            };
            (format!("{verb}: {}", paths.join(", ")), failed)
        }
        "mcpToolCall" => {
            if let Some(message) = item["error"]["message"].as_str() {
                return (message.to_owned(), true);
            }
            let content = &item["result"]["content"];
            let text = content
                .as_array()
                .into_iter()
                .flatten()
                .filter_map(|part| part["text"].as_str())
                .collect::<Vec<_>>()
                .join("\n");
            let is_error = failed || item["result"]["isError"].as_bool() == Some(true);
            (text, is_error)
        }
        _ => (status.to_owned(), failed),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_messages() {
        assert_eq!(
            Incoming::parse(json!({"id": 1, "result": {"ok": true}})),
            Some(Incoming::Response {
                id: json!(1),
                result: Ok(json!({"ok": true}))
            })
        );
        assert_eq!(
            Incoming::parse(json!({"error": {"code": -1, "message": "no"}, "id": 2})),
            Some(Incoming::Response {
                id: json!(2),
                result: Err("no".into())
            })
        );
        assert!(matches!(
            Incoming::parse(json!({"id": "s1", "method": "execCommandApproval", "params": {}})),
            Some(Incoming::Request { method, .. }) if method == "execCommandApproval"
        ));
        assert!(matches!(
            Incoming::parse(json!({"method": "turn/started"})),
            Some(Incoming::Notification {
                params: Value::Null,
                ..
            })
        ));
        assert_eq!(Incoming::parse(json!([1])), None);
        assert_eq!(Incoming::parse(json!({"id": 3})), None);
    }

    #[test]
    fn usage_maps_fields_and_turn_deltas() {
        let total = json!({"inputTokens": 1200, "cachedInputTokens": 1000, "outputTokens": 30,
            "reasoningOutputTokens": 10, "totalTokens": 1230});
        assert_eq!(
            usage_from_codex(&total),
            Usage {
                input_tokens: 1200,
                output_tokens: 30,
                cache_read_tokens: 1000,
                cache_write_tokens: 0,
            }
        );
        let mut mapper = Mapper::new("t");
        for (input, cached, output) in [(1200, 1000, 30), (3000, 2400, 70)] {
            mapper.map(
                "thread/tokenUsage/updated",
                &json!({"threadId": "t", "tokenUsage": {"total": {"inputTokens": input,
                    "cachedInputTokens": cached, "outputTokens": output}, "last": {}}}),
            );
            let step = mapper.map(
                "turn/completed",
                &json!({"threadId": "t", "turn": {"id": "u", "status": "completed", "items": []}}),
            );
            assert!(step.done);
            assert_eq!(
                step.events.last(),
                Some(&StreamEvent::Done(StopReason::EndTurn))
            );
        }
        // The second turn reports only its own tokens.
        let mut again = Mapper::new("t");
        again.baseline = usage_from_codex(
            &json!({"inputTokens": 1200, "cachedInputTokens": 1000, "outputTokens": 30}),
        );
        again.latest = Some(usage_from_codex(
            &json!({"inputTokens": 3000, "cachedInputTokens": 2400, "outputTokens": 70}),
        ));
        let step = again.map("turn/completed", &json!({"turn": {"status": "completed"}}));
        assert_eq!(
            step.events[0],
            StreamEvent::Usage(Usage {
                input_tokens: 1800,
                output_tokens: 40,
                cache_read_tokens: 1400,
                cache_write_tokens: 0,
            })
        );
    }

    #[test]
    fn failed_turns_are_typed() {
        let mut mapper = Mapper::new("t");
        let step = mapper.map(
            "turn/completed",
            &json!({"turn": {"status": "failed", "error": {"message": "limit", "codexErrorInfo": "usageLimitExceeded"}}}),
        );
        assert!(matches!(step.error, Some(ProviderError::UsageLimit { .. })));
        let step = mapper.map(
            "turn/completed",
            &json!({"turn": {"status": "failed", "error": {"message": "401", "codexErrorInfo": "unauthorized"}}}),
        );
        let err = step.error.unwrap();
        assert!(err.to_string().contains("rozu auth login codex"), "{err}");
        mapper.map(
            "error",
            &json!({"error": {"message": "stream broke", "codexErrorInfo": {"responseStreamDisconnected": {}}}, "willRetry": false}),
        );
        let step = mapper.map("turn/completed", &json!({"turn": {"status": "failed"}}));
        assert_eq!(
            step.error,
            Some(ProviderError::Api {
                code: Some("responseStreamDisconnected".into()),
                message: "stream broke".into()
            })
        );
        let step = mapper.map(
            "turn/completed",
            &json!({"turn": {"status": "interrupted"}}),
        );
        assert_eq!(step.error, Some(ProviderError::Cancelled));
    }

    #[test]
    fn items_map_to_tool_calls_and_results() {
        let mut mapper = Mapper::new("t");
        let mut events = Vec::new();
        for (method, params) in [
            (
                "item/started",
                json!({"item": {"type": "commandExecution", "id": "c1", "command": "ls", "cwd": "/w", "commandActions": [], "status": "inProgress"}}),
            ),
            (
                "item/completed",
                json!({"item": {"type": "commandExecution", "id": "c1", "command": "ls", "status": "failed", "aggregatedOutput": "boom", "exitCode": 2}}),
            ),
            (
                "item/completed",
                json!({"item": {"type": "mcpToolCall", "id": "m1", "server": "rozu", "tool": "read_file", "arguments": {"path": "a"}, "status": "completed", "result": {"content": [{"type": "text", "text": "hi"}]}}}),
            ),
            (
                "item/completed",
                json!({"item": {"type": "agentMessage", "id": "a1", "text": "Done."}}),
            ),
            (
                "item/agentMessage/delta",
                json!({"itemId": "a2", "delta": "x"}),
            ),
            (
                "item/completed",
                json!({"item": {"type": "agentMessage", "id": "a2", "text": "x"}}),
            ),
            (
                "item/agentMessage/delta",
                json!({"threadId": "other", "itemId": "a3", "delta": "skipped"}),
            ),
        ] {
            events.extend(mapper.map(method, &params).events);
        }
        assert_eq!(
            events,
            [
                StreamEvent::ToolCallStart {
                    id: "c1".into(),
                    name: SHELL_TOOL.into()
                },
                StreamEvent::ToolCallArgsDelta {
                    id: "c1".into(),
                    json: r#"{"command":"ls"}"#.into()
                },
                StreamEvent::ToolCallEnd { id: "c1".into() },
                StreamEvent::ToolResult {
                    id: "c1".into(),
                    output: "boom\n[exit code 2]".into(),
                    is_error: true
                },
                StreamEvent::ToolCallStart {
                    id: "m1".into(),
                    name: "read_file".into()
                },
                StreamEvent::ToolCallArgsDelta {
                    id: "m1".into(),
                    json: r#"{"path":"a"}"#.into()
                },
                StreamEvent::ToolCallEnd { id: "m1".into() },
                StreamEvent::ToolResult {
                    id: "m1".into(),
                    output: "hi".into(),
                    is_error: false
                },
                StreamEvent::TextDelta("Done.".into()),
                StreamEvent::TextDelta("x".into()),
            ]
        );
    }

    #[test]
    fn account_status_reads_only_the_type() {
        assert_eq!(
            account_status(
                &json!({"account": {"type": "chatgpt", "email": "a@b.c", "planType": "plus"}, "requiresOpenaiAuth": true})
            ),
            AccountStatus::LoggedIn("chatgpt".into())
        );
        assert_eq!(
            account_status(&json!({"account": null, "requiresOpenaiAuth": true})),
            AccountStatus::NotLoggedIn
        );
        assert_eq!(
            account_status(&json!({"requiresOpenaiAuth": false})),
            AccountStatus::NotRequired
        );
    }
}
